namespace OneMusic.UI;

/// <summary>알림 카드 버튼용 흰 아이콘 (64px PNG, base64) — 패키지 없는 앱이라 파일로 풀어 놓고 경로로 쓴다</summary>
internal static class NotifyIcons
{
    public const string Prev = "";
    public const string Next = "";
    public const string Play = "";
    public const string Pause = "";

    /// <summary>앱 데이터 폴더에 풀어 둔 아이콘 파일 경로</summary>
    public static Uri File(string name, string b64)
    {
        var path = IOPath.Combine(OneMusic.Core.Log.AppDataDir, $"notify-{name}.png");
        if (!System.IO.File.Exists(path)) System.IO.File.WriteAllBytes(path, Convert.FromBase64String(b64));
        return new Uri(path);
    }
}
